SELECT FROM skill_job j LEFT JOIN skill_dependency_metric m ON m.id = j.metric_id
AND j.enabled = #{enabled} AND j.name LIKE CONCAT('%', #{keyword}, '%') AND j.created_by = #{createdBy}
ORDER BY j.created_at DESC

SELECT  FROM skill_job_execution
WHERE job_id = #{jobId}
AND status = #{status}
ORDER BY created_at DESC
